    values = context["values"]
    contrib = [poly(x) for x in values]
    for step in range(3):
        total = 0
        new = []
        for c in contrib:
            total = total + c
            new.append(total)
        contrib = new
    if len(contrib) == 0:
        return 0
    return contrib[-1]

