def contributions(values, a, b, c, g, mode):
    out = []
    total = 0
    for i in range(len(values)):
        x = values[i]
        base = poly(x, a, b, c)
        if i == 0:
            extra = 0
        elif mode == 0:
            extra = g * x * values[i - 1]
        else:
            extra = g * x * total
        out.append(base + extra)
        total = total + x
    return out

def passes(seq, n):
    cur = seq
    for _ in range(n):
        nxt = []
        run = 0
        for v in cur:
            run = run + v
            nxt.append(run)
        cur = nxt
    return cur

def evaluate(values, a, b, c, g, mode, n):
    if not values:
        return 0
    return passes(contributions(values, a, b, c, g, mode), n)[-1]

