def poly(x):
    return 2 * x + 1 * x * x + 1 * x * x * x

def contribution(values, i):
    x = values[i]
    prev = values[i - 1] if i > 0 else 0
    total = sum(values[:i])
    return poly(x) + 1 * x * prev + 1 * x * total

def cumulative(values):
    out = []
    running = 0
    for v in values:
        running = running + v
        out.append(running)
    return out

def readout(values):
    if not values:
        return 0
    contribs = [contribution(values, i) for i in range(len(values))]
    result = contribs
    for _ in range(3):
        result = cumulative(result)
    return result[-1]

def investigate(context, acquire):
    return readout(context["values"])

